export function insertToExcel(value, type) {
  // Build the formula string based on the type and value
  let formula = "";
  switch (type) {
    case "subject":
      formula = `=FACT.PULL("${value}", "Total revenues", "Actual", "Annual", "2024-01-01")`;
      break;
    case "metric":
      formula = `=FACT.PULL("Asset: Bring Energy", "${value}", "Actual", "Annual", "2024-01-01")`;
      break;
    case "scenario":
      formula = `=FACT.PULL("Asset: Bring Energy", "Total revenues", "${value}", "Annual", "2024-01-01")`;
      break;
    case "period":
      formula = `=FACT.PULL("Asset: Bring Energy", "Total revenues", "Actual", "${value}", "2024-01-01")`;
      break;
    default:
      formula = value;
  }

  // Use Excel.run to set the formula in the active cell
  if (window.Excel && Excel.run) {
    Excel.run(async (context) => {
      const range = context.workbook.getActiveCell();
      range.formulas = [[formula]];
      await context.sync();
    }).catch(function (error) {
      console.error("Error inserting formula:", error);
      alert("Error inserting formula: " + error.message);
    });
  } else {
    alert("Excel JavaScript API not available. Formula: " + formula);
  }
}

export const handleRefresh = async () => {
  try {
    await Excel.run(async (context) => {
      const range = context.workbook.getSelectedRange();
      range.load("formulas");
      await context.sync();
      const formula = range.formulas[0][0];
      if (formula && formula.startsWith("=FACT.PULL")) {
        range.formulas = [[formula]];
        await context.sync();
      }
    });
  } catch (error) {
    console.error("Error refreshing formula:", error);
  }
};

export const refreshAllFormulas = async () => {
  try {
    await Excel.run(async (context) => {
      const sheet = context.workbook.getActiveWorksheet();
      const usedRange = sheet.getUsedRange();
      usedRange.load("formulas");
      await context.sync();
      const formulas = usedRange.formulas;
      for (let i = 0; i < formulas.length; i++) {
        for (let j = 0; j < formulas[i].length; j++) {
          const formula = formulas[i][j];
          if (formula && formula.startsWith("=FACT.PULL")) {
            const cell = usedRange.getCell(i, j);
            cell.formulas = [[formula]];
          }
        }
      }
      await context.sync();
    });
  } catch (error) {
    console.error("Error refreshing all formulas:", error);
  }
}; 