import React, { useState } from "react";
import { Input, makeStyles, Button, Tag } from "@fluentui/react-components";

const useStyles = makeStyles({
  panel: {
    background: "#fff",
    borderRadius: 16,
    boxShadow: "0 4px 24px 0 rgba(60, 72, 100, 0.12)",
    padding: 24,
    paddingLeft: 32,
    paddingRight: 32,
    width: "95%",
    maxWidth: "100%",
    margin: "0 12px 32px 12px",
    position: "relative",
    border: "1px solid #e0e0e0",
    minHeight: 120,
    boxSizing: "border-box",
    display: "flex",
    flexDirection: "column",
    height: 420,
  },
  title: {
    fontSize: 20,
    fontWeight: 700,
    marginBottom: 8,
    textAlign: "left",
    marginLeft: 20,
    marginRight: 20,
  },
  filterRow: {
    display: "flex",
    gap: 12,
    marginBottom: 12,
    marginTop: 4,
    flexWrap: "wrap",
    marginLeft: 20,
    marginRight: 20,
    paddingLeft: 0,
    paddingRight: 0,
  },
  tagActive: {
    background: "#023a66",
    color: "#fff",
    borderColor: "#023a66",
  },
  searchBox: {
    marginBottom: 16,
    width: "100%",
    marginLeft: 20,
    marginRight: 20,
    paddingLeft: 0,
    paddingRight: 0,
  },
  list: {
    flex: 1,
    minHeight: 0,
    overflowY: "auto",
    padding: 0,
    margin: 0,
    listStyle: "none",
    background: "#fff",
    borderRadius: 8,
    boxShadow: "0 2px 8px 0 rgba(60, 72, 100, 0.10)",
  },
  listItem: {
    padding: "18px 20px",
    borderBottom: "1px solid #eee",
    cursor: "pointer",
    fontSize: 17,
    background: "#fff",
    transition: "background 0.2s",
    '&:hover': {
      background: "#f3f8fc",
    },
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
  },
  listItemTitle: {
    fontWeight: 600,
    fontSize: 17,
    marginBottom: 2,
  },
  listItemDesc: {
    fontSize: 13,
    color: "#888",
    marginBottom: 2,
  },
  listItemUnit: {
    fontSize: 12,
    color: "#666",
    marginTop: 2,
  },
});

const titles = {
  subject: "Lookup Subject",
  metric: "Lookup Metric",
  scenario: "Lookup Scenario",
  period: "Select Period",
};

const mockSubjects = [
  // Funds
  { type: "Fund", name: "Green Fund" },
  { type: "Fund", name: "Future Growth" },
  // Companies
  { type: "Company", name: "Blue Power", fund: "Green Fund" },
  { type: "Company", name: "Red Renewables", fund: "Future Growth" },
  // Assets
  { type: "Asset", name: "Solar One", company: "Blue Power" },
  { type: "Asset", name: "Wind Prime", company: "Red Renewables" },
];

const mockMetrics = [
  { title: "Total revenues", desc: "Custom company-level metric for 'Blue Power'", unit: "CURRENCY" },
  { title: "Gross margin", desc: "Custom company-level metric for 'Red Renewables'", unit: "CURRENCY" },
  { title: "Debt drawdowns", desc: "Custom company-level metric for 'Red Renewables'", unit: "CURRENCY" },
  { title: "Operating expenses", desc: "Custom company-level metric for 'Blue Power'", unit: "CURRENCY" },
  { title: "Net profit", desc: "Custom company-level metric for 'Red Renewables'", unit: "CURRENCY" },
  { title: "EBITDA", desc: "Custom company-level metric for 'Blue Power'", unit: "CURRENCY" },
  { title: "Cash flow", desc: "Custom company-level metric for 'Red Renewables'", unit: "CURRENCY" },
];

const scenarios = [
  "Actual",
  "Budget",
  "Forecast"
];

const periodOptions = [
  "Monthly",
  "Quarterly",
  "Semi-annually",
  "Annual",
  "YTD",
];

const filterTags = {
  subject: ["Asset", "Company", "Fund"],
  metric: ["Custom ✓", "Standard ✓", "Asset-level ✓", "Company-level ✓", "Fund-level ✓"],
};

const LookupPanel = ({ type, onSelect }) => {
  const styles = useStyles();
  const [search, setSearch] = useState("");
  const [activeFilters, setActiveFilters] = useState([]);

  let items = [];
  if (type === "subject") items = mockSubjects;
  if (type === "metric") items = mockMetrics;
  if (type === "scenario") items = scenarios;
  if (type === "period") items = periodOptions;

  // Filtering logic for tags
  let filtered = items;
  if (type === "subject" && activeFilters.length > 0) {
    filtered = filtered.filter(item =>
      activeFilters.some(f => item.name.toLowerCase().startsWith(f.toLowerCase()))
    );
  }
  if (type === "metric" && activeFilters.length > 0) {
    filtered = filtered.filter(item =>
      activeFilters.some(f => {
        if (f === "Custom ✓") return item.desc && item.desc.toLowerCase().includes("custom");
        if (f === "Standard ✓") return item.desc && item.desc.toLowerCase().includes("standard");
        if (f === "Asset-level ✓") return item.desc && item.desc.toLowerCase().includes("asset-level");
        if (f === "Company-level ✓") return item.desc && item.desc.toLowerCase().includes("company-level");
        if (f === "Fund-level ✓") return item.desc && item.desc.toLowerCase().includes("fund-level");
        return false;
      })
    );
  }
  // Search filter
  if (type !== "period") {
    filtered = filtered.filter(item => {
      let val = "";
      if (type === "subject") {
        val = item.name;
      } else if (item.title) {
        val = item.title;
      } else if (typeof item === "string") {
        val = item;
      }
      return val.toLowerCase().includes(search.toLowerCase());
    });
  }

  const handleTagClick = (tag) => {
    setActiveFilters((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
  };

  return (
    <div className={styles.panel}>
      <div className={styles.title}>{titles[type]}</div>
      {(type === "subject" || type === "metric") && (
        <div className={styles.filterRow}>
          {filterTags[type].map((tag) => (
            <Tag
              key={tag}
              size="medium"
              appearance={activeFilters.includes(tag) ? "filled" : "outline"}
              className={activeFilters.includes(tag) ? styles.tagActive : undefined}
              onClick={() => handleTagClick(tag)}
              style={{ cursor: "pointer" }}
            >
              {tag}
            </Tag>
          ))}
        </div>
      )}
      {type !== "period" && (
        <Input
          className={styles.searchBox}
          placeholder="Search..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          autoFocus
        />
      )}
      <ul className={styles.list}>
        {filtered.length === 0 && <li style={{ padding: 12, color: '#888' }}>No results found.</li>}
        {filtered.map((item, idx) => {
          // SUBJECT LOGIC
          if (type === "subject") {
            let title = `${item.type}: ${item.name}`;
            let desc = null;
            if (item.type === "Company" && item.fund) desc = `PortCo of ${item.fund}`;
            if (item.type === "Asset" && item.company) desc = `Asset of ${item.company}`;
            // Fund: no desc
            return (
              <li
                key={title + idx}
                className={styles.listItem}
                onClick={() => onSelect(title)}
                tabIndex={0}
                onKeyDown={e => (e.key === 'Enter' ? onSelect(title) : undefined)}
              >
                <span className={styles.listItemTitle}>{title}</span>
                {desc && <span className={styles.listItemDesc}>{desc}</span>}
              </li>
            );
          }
          // METRIC LOGIC
          if (type === "metric") {
            return (
              <li
                key={(item.title || item) + idx}
                className={styles.listItem}
                onClick={() => onSelect(item.title || item)}
                tabIndex={0}
                onKeyDown={e => (e.key === 'Enter' ? onSelect(item.title || item) : undefined)}
              >
                <span className={styles.listItemTitle}>{item.title || item}</span>
                {item.desc && <span className={styles.listItemDesc}>{item.desc}</span>}
                {item.unit && <span className={styles.listItemUnit}>Unit: {item.unit}</span>}
              </li>
            );
          }
          // SCENARIO & PERIOD LOGIC
          return (
            <li
              key={(item.title || item) + idx}
              className={styles.listItem}
              onClick={() => onSelect(item.title || item)}
              tabIndex={0}
              onKeyDown={e => (e.key === 'Enter' ? onSelect(item.title || item) : undefined)}
            >
              <span className={styles.listItemTitle}>{item.title || item}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

export default LookupPanel; 