import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Button, Input, Label, makeStyles, tokens } from "@fluentui/react-components";
import { ArrowRight24Regular } from "@fluentui/react-icons";
import { Download, RefreshCw, Upload } from "lucide-react";
import Logo from "../../../../assets/Picture2.png";

const useStyles = makeStyles({
  authContainer: {
    height: "100%",
    minHeight: 0,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: "#f4f6fa",
    fontFamily: "'Segoe UI', sans-serif",
    padding: "32px 16px 32px 16px",
    boxSizing: "border-box",
  },
  authCard: {
    background: "#fff",
    borderRadius: "18px",
    boxShadow: "0 4px 24px 0 rgba(60, 72, 100, 0.12)",
    padding: "16px",
    width: "100%",
    maxWidth: "400px",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    margin: 0,
  },
  logoContainer: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
  },
  logo: {
    width: "200px",
    height: "80px",
    borderRadius: "50%",
    boxShadow: "0 2px 8px 0 rgba(60, 72, 100, 0.10)",
    background: "#fff",
    objectFit: "cover",
  },
  subtitle: {
    color: "#737373",
    fontSize: "13px",
    fontWeight: 500,
    marginBottom: "16px",
    textAlign: "center",
  },
  featuresSection: {
    width: "100%",
    background: "#fff",
    borderRadius: "12px",
    display: "flex",
    flexDirection: "column",
    gap: 0,
    boxSizing: "border-box",
    marginBottom: "8px",
  },
  featureItem: {
    display: "flex",
    alignItems: "center",
    fontSize: "13px",
    fontWeight: 600,
    padding: "2px 0 2px 8px",
    color: "#023a66",
  },
  featureIcon: {
    marginRight: "10px",
    fontSize: "18px",
    opacity: 0.85,
  },
  formContainer: {
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: "4px",
    marginTop: "4px",
    marginBottom: "4px",
  },
  label: {
    color: "#023a66",
    fontSize: "12px",
    fontWeight: 600,
    marginBottom: "1px",
    marginTop: "4px",
  },
  input: {
    width: "100%",
  },
  submitButton: {
    marginTop: "8px",
    width: "100%",
    fontWeight: 700,
    fontSize: "16px",
    padding: "8px 0",
  },
  errorMessage: {
    color: "#d32f2f",
    fontSize: "12px",
    textAlign: "center",
    marginTop: "4px",
  },
  buttonGrid: {
    display: "grid",
    gridTemplateColumns: "1fr 1fr",
    gap: 32,
    width: "100%",
    maxWidth: 500,
    marginBottom: 40,
    marginTop: 12,
    background: "#f0f0f0",
  },
  button: {
    minHeight: 40,
    fontSize: 16,
    fontWeight: 500,
    borderRadius: 12,
    width: "100%",
    boxShadow: "0 1px 4px 0 rgba(60, 72, 100, 0.10)",
    background: tokens.colorBrandBackground,
    color: tokens.colorNeutralForegroundOnBrand,
    transition: "background 0.2s, color 0.2s",
    letterSpacing: 0.2,
    margin: 0,
    border: "none",
    outline: "none",
    ':hover': {
      background: tokens.colorBrandBackgroundHover,
      color: tokens.colorNeutralForegroundOnBrand,
    },
  },
});

const features = [
  { icon: <Download style={{ color: "#023a66" }} />, text: "Pull from FactFolio" },
  { icon: <Upload style={{ color: "#0aa095" }} />, text: "Upload to FactFolio" },
  { icon: <RefreshCw style={{ color: "#63cad9" }} />, text: "Refresh from FactFolio" },
];

const Login = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [apiKey, setApiKey] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");
  const navigate = useNavigate();
  const styles = useStyles();

  const handleSignIn = async (e) => {
    e.preventDefault();
    setError("");
    if (!username || !password || !apiKey) {
      setError("Please fill out all fields.");
      return;
    }
    setIsLoading(true);
    try {
      console.log({ username, password, apiKey });
      window.localStorage.setItem("folioApiKey", apiKey);
      navigate("/home");
    } catch (err) {
      setError("An error occurred during login.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={styles.authContainer}>
      <div className={styles.authCard}>
        <div className={styles.logoContainer}>
          <img src={Logo} alt="FactFolio Logo" className={styles.logo} />
        </div>
        <div className={styles.featuresSection}>
          {features.map((feature, idx) => (
            <div className={styles.featureItem} key={idx}>
              <span className={styles.featureIcon}>{feature.icon}</span>
              <span>{feature.text}</span>
            </div>
          ))}
        </div>
        <form className={styles.formContainer} onSubmit={handleSignIn} autoComplete="off">
          <Label htmlFor="username" className={styles.label}>Username</Label>
          <Input
            id="username"
            className={styles.input}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="username"
            required
          />
          <Label htmlFor="password" className={styles.label}>Password</Label>
          <Input
            id="password"
            className={styles.input}
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="password"
            required
          />
          <Label htmlFor="apiKey" className={styles.label}>API Key</Label>
          <Input
            id="apiKey"
            className={styles.input}
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            placeholder="api key"
            required
          />
          {error && <div className={styles.errorMessage}>{error}</div>}
          <Button
            className={styles.submitButton}
            appearance="primary"
            type="submit"
            disabled={isLoading}
            icon={<ArrowRight24Regular />}
          >
            {isLoading ? "Connecting..." : "Login to FactFolio"}
          </Button>
        </form>
      </div>
    </div>
  );
};

export default Login; 