import React, { useState, useEffect } from "react";
import { Button, makeStyles, tokens } from "@fluentui/react-components";
import LookupPanel from "./LookupPanel";
import Header from "./Header";
import { insertToExcel, handleRefresh, refreshAllFormulas } from "../utils/office-document";
import { useNavigate } from "react-router-dom";
const useStyles = makeStyles({
  container: {
    minHeight: "100vh",
    background: tokens.colorNeutralBackground2,
    display: "flex",
    flexDirection: "column",
  },
  content: {
    padding: 24,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    flex: 1,
  },
  title: {
    fontSize: 22,
    fontWeight: 700,
    marginBottom: 32,
    color: tokens.colorNeutralForeground1,
    textAlign: "center",
    marginLeft: 20,
    marginRight: 20,
  },
  buttonRow: {
    display: "flex",
    flexDirection: "row",
    justifyContent: "center",
    gap: 24,
    width: "100%",
    maxWidth: "100%",
    marginBottom: 32,
    boxSizing: "border-box",
    marginLeft: 20,
    marginRight: 20,
  },
  button: {
    minHeight: 44,
    fontSize: 16,
    fontWeight: 500,
    borderRadius: 12,
    width: "40%",
    boxShadow: "0 1px 4px 0 rgba(60, 72, 100, 0.10)",
    background: tokens.colorBrandBackground,
    color: tokens.colorNeutralForegroundOnBrand,
    transition: "background 0.2s, color 0.2s",
    letterSpacing: 0.2,
    margin: 0,
    border: "none",
    outline: "none",
    ':hover': {
      background: tokens.colorBrandBackgroundHover,
      color: tokens.colorNeutralForegroundOnBrand,
    },
  },
});

const Home = () => {
  const styles = useStyles();
  const navigate = useNavigate();
  const [openPanel, setOpenPanel] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  useEffect(() => {
    const apiKey = window.localStorage.getItem("folioApiKey");
    if (!apiKey || apiKey === "") {
      navigate("/");
    } 
  }, []);

  const handleSelect = (value) => {
    // Insert the value (or a dummy value) directly into the cell
    if (window.Excel && Excel.run) {
      Excel.run(async (context) => {
        const range = context.workbook.getActiveCell();
        range.values = [[typeof value === 'string' ? value : JSON.stringify(value)]];
        await context.sync();
      }).catch(function (error) {
        console.error("Error inserting value:", error);
        alert("Error inserting value: " + error.message);
      });
    } else {
      alert("Excel JavaScript API not available. Value: " + value);
    }
  };



  return (
    <div className={styles.container}>
     
        <>
          <Header  />
          <div className={styles.content}>
            <div className={styles.title}>Look-up data references to use in formulas:</div>
            <div className={styles.buttonRow}>
              <Button className={styles.button} appearance="primary" style={{marginRight:"10px"}} onClick={() => setOpenPanel('subject')}>Subject</Button>
              <Button className={styles.button} appearance="primary" onClick={() => setOpenPanel('metric')}>Metric</Button>
            </div>
            <div className={styles.buttonRow} style={{marginTop:"10px"}}>
              <Button className={styles.button} appearance="primary" style={{marginRight:"10px"}} onClick={() => setOpenPanel('scenario')}>Scenario</Button>
              <Button className={styles.button} appearance="primary" onClick={() => setOpenPanel('period')}>Period</Button>
            </div>
            {openPanel && (
              <LookupPanel
                type={openPanel}
                onSelect={handleSelect}
              />
            )}
          </div>
        </>
      
    </div>
  );
};

export default Home; 